import { describe, it, before, after } from "node:test";
import assert from "node:assert/strict";
import { createServer } from "../src/server.js";

let server: Awaited<ReturnType<typeof createServer>>;
const PORT = 3010;
const BASE_URL = `http://localhost:${PORT}`;

async function fetchJson(path: string, options: RequestInit = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    ...options,
    headers: {
      "Content-Type": "application/json",
      ...options.headers,
    },
  });
  const text = await res.text();
  let body: unknown = null;
  if (text) {
    try {
      body = JSON.parse(text);
    } catch {
      body = text;
    }
  }
  return { status: res.status, body, headers: res.headers };
}

function semearEncontro(cancelada = false) {
  const db = server.db;
  db.run(
    "INSERT INTO atividades (id, titulo, tipo, sala_id, vagas, situacao) VALUES (?, ?, 'palestra', 'sala-101', 40, ?)",
    ["atv_a1b2c3d4", "Palestra de teste", cancelada ? "cancelada" : "prevista"]
  );
  db.run(
    "INSERT INTO encontros (id, atividade_id, inicio, fim, ordem) VALUES ('enc_5e6f7a8b', 'atv_a1b2c3d4', ?, ?, 1)",
    ["2026-10-19T10:00:00-03:00", "2026-10-19T11:00:00-03:00"]
  );
}

async function resetar(agora: string) {
  await fetchJson("/_teste/reset", { method: "POST" });
  await fetchJson("/_teste/relogio", {
    method: "PUT",
    body: JSON.stringify({ agora }),
  });
  semearEncontro();
}

describe("M3 Fatia 1 - Código do encontro", () => {
  before(async () => {
    process.env.MODO_TESTE = "1";
    server = await createServer();
    await new Promise<void>((resolve) => server.listen({ port: PORT }, resolve));
  });

  after(async () => {
    await server.close();
  });

  it("R1 - bordas da janela de obtenção: início - 15 min e início + 30 min retornam 200", async () => {
    await resetar("2026-10-19T09:45:00-03:00");
    const r1 = await fetchJson("/encontros/enc_5e6f7a8b/codigo", {
      headers: { "X-Usuario": "org-ana" },
    });
    assert.equal(r1.status, 200);
    const body1 = r1.body as {
      encontroId: string;
      codigo: string;
      trocaEm: string;
      validoAte: string;
    };
    assert.equal(body1.encontroId, "enc_5e6f7a8b");
    assert.match(body1.codigo, /^[A-Z0-9]{6}$/);
    assert.ok(body1.trocaEm);
    assert.ok(body1.validoAte);

    await fetchJson("/_teste/relogio", {
      method: "PUT",
      body: JSON.stringify({ agora: "2026-10-19T10:30:00-03:00" }),
    });
    const r2 = await fetchJson("/encontros/enc_5e6f7a8b/codigo", {
      headers: { "X-Usuario": "org-ana" },
    });
    assert.equal(r2.status, 200);
  });
});

import { FastifyInstance } from "fastify";
import { verifyAuth } from "../middleware/auth.js";
import { obterRelogioTeste } from "../db.js";

const ALFABETO = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
const MINUTOS_ANTES = 15 * 60 * 1000;
const MINUTOS_DEPOIS = 30 * 60 * 1000;
const MILIS_DA_JANELA = 60 * 1000;

function agoraServidor(app: FastifyInstance): Date {
  if (process.env.MODO_TESTE === "1") {
    return new Date(obterRelogioTeste(app.db));
  }
  return new Date();
}

function hashString(s: string): number {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

function codigoDaJanela(encontroId: string, janelaInicio: number): string {
  const base = `${encontroId}|${janelaInicio}`;
  let codigo = "";
  for (let i = 0; i < 6; i++) {
    const h = hashString(`${base}#${i}`);
    codigo += ALFABETO[h % ALFABETO.length];
  }
  return codigo;
}

function linhaParaObjeto(cols: string[], vals: unknown[]): Record<string, unknown> {
  const row: Record<string, unknown> = {};
  cols.forEach((c, i) => { row[c] = vals[i]; });
  return row;
}

export function registrarRotasEncontros(app: FastifyInstance) {
  app.get(
    "/encontros/:id/codigo",
    { preHandler: verifyAuth },
    async (req, reply) => {
      const usuario = req.usuario;
      if (!usuario || usuario.papel !== "organizacao") {
        return reply.code(403).send({
          erro: "SOMENTE_ORGANIZACAO",
          mensagem: "Apenas a organização obtém o código do encontro",
        });
      }

      const { id } = req.params as { id: string };
      const db = app.db;
      const result = db.exec(
        `SELECT e.id, e.inicio, a.situacao
         FROM encontros e
         JOIN atividades a ON a.id = e.atividade_id
         WHERE e.id = ?`,
        [id]
      );
      if (result.length === 0 || result[0].values.length === 0) {
        return reply.code(404).send({
          erro: "NAO_ENCONTRADO",
          mensagem: "Encontro não encontrado",
        });
      }

      const row = linhaParaObjeto(result[0].columns, result[0].values[0]);

      if (row.situacao === "cancelada") {
        return reply.code(422).send({
          erro: "ATIVIDADE_CANCELADA",
          mensagem: "A atividade do encontro foi cancelada",
        });
      }

      const inicio = new Date(row.inicio as string).getTime();
      const agora = agoraServidor(app).getTime();
      if (agora < inicio - MINUTOS_ANTES || agora > inicio + MINUTOS_DEPOIS) {
        return reply.code(422).send({
          erro: "FORA_DA_JANELA",
          mensagem: "Fora da janela de obtenção do código",
        });
      }

      const janelaInicio = Math.floor(agora / MILIS_DA_JANELA) * MILIS_DA_JANELA;
      return reply.send({
        encontroId: id,
        codigo: codigoDaJanela(id, janelaInicio),
        trocaEm: new Date(janelaInicio + MILIS_DA_JANELA).toISOString(),
        validoAte: new Date(janelaInicio + 2 * MILIS_DA_JANELA).toISOString(),
      });
    }
  );
}

